//! Match states captured from Flash, never generated by Rust.
use sportheads_core::{
    game::{Game, Phase},
    math::Vec2,
    powerups::Kind,
};

fn compare(fixture: &str) {
    let mut game = Game::new(123);
    game.phase = Phase::Playing;
    game.countdown = 0;
    game.world.bodies[game.ball].set_transform(Vec2::new(400.0, 200.0), 0.0);
    game.world.bodies[game.ball].velocity = Vec2::new(0.0, -100.0);
    let mut position_tolerance = 1e-7;
    let mut velocity_tolerance = 1e-7;
    for (line_number, line) in fixture.lines().enumerate() {
        if line.trim().is_empty() || line.starts_with('#') {
            continue;
        }
        let words: Vec<_> = line.split_whitespace().collect();
        match words[0] {
            "tolerances" => {
                position_tolerance = words[1].parse().unwrap();
                velocity_tolerance = words[2].parse().unwrap();
            }
            "collect" => game.collect(
                Kind::from_id(words[1].parse().unwrap()).expect("valid original bonus ID"),
                words[2].parse().unwrap(),
            ),
            "ball" => {
                let v: Vec<f64> = words[1..].iter().map(|v| v.parse().unwrap()).collect();
                game.world.bodies[game.ball].set_transform(Vec2::new(v[0], v[1]), 0.0);
                game.world.bodies[game.ball].velocity = Vec2::new(v[2], v[3]);
            }
            "initial" => {}
            "mask" => game.step(words[1].parse().unwrap()),
            "expect" => {
                let i = match words[1] {
                    "opp" => game.player[0],
                    "hero" => game.player[1],
                    "ball" => game.ball,
                    "oppracket" => game.foot[0],
                    "racket" => game.foot[1],
                    name => panic!("unknown body {name}"),
                };
                let b = &game.world.bodies[i];
                let values = [
                    b.position.x,
                    b.position.y,
                    b.velocity.x,
                    b.velocity.y,
                    b.angle,
                    b.omega,
                ];
                for (field, actual) in values.iter().enumerate() {
                    let expected: f64 = words[field + 2].parse().unwrap();
                    let tolerance = if matches!(field, 2 | 3 | 5) {
                        velocity_tolerance
                    } else {
                        position_tolerance
                    };
                    assert!(
                        (actual - expected).abs() <= tolerance,
                        "line {}, body {}, field {}: {} vs Flash {}",
                        line_number + 1,
                        words[1],
                        field,
                        actual,
                        expected
                    );
                }
            }
            command => panic!("unknown command {command}"),
        }
    }
}
#[test]
fn neutral_match_against_flash() {
    compare(include_str!("fixtures/match/neutral.txt"));
}

#[test]
fn central_collision_match_against_flash() {
    compare(include_str!("fixtures/match/center.txt"));
}

#[test]
fn roof_nudge_match_against_flash() {
    compare(include_str!("fixtures/match/roof.txt"));
}

#[test]
fn large_player_first_120_frames_against_flash() {
    compare(include_str!("fixtures/match/big-player.txt"));
}
